"use client";

// La voz del asistente en el teléfono: pide el audio a /api/voz/hablar (voz natural de OpenAI) y lo reproduce.
// En iPhone el audio solo suena si antes hubo un toque: por eso `desbloquear()` se llama al tocar el micrófono o "Enviar".

let audio: HTMLAudioElement | null = null;
let desbloqueado = false;
let sinIA = false;
let actual = 0;
const SILENCIO = "data:audio/wav;base64,";

function el() {
  if (!audio && typeof Audio !== "undefined") { audio = new Audio(); audio.preload = "auto"; (audio as HTMLAudioElement & { playsInline?: boolean }).playsInline = true; }
  return audio;
}

/** Se llama dentro de un toque de Andrea para que después el teléfono deje sonar la voz. */
export function desbloquear() {
  const a = el();
  if (!a || desbloqueado) return;
  try { a.src = SILENCIO; a.volume = 0; const p = a.play(); p?.then(() => { a.pause(); a.volume = 1; desbloqueado = true; }).catch(() => { a.volume = 1; }); } catch {}
}

export function callar() {
  actual++;
  try { audio?.pause(); } catch {}
  try { window.speechSynthesis?.cancel(); } catch {}
}

/** Dice el texto con la voz natural. Termina cuando acaba de hablar (o enseguida si no se pudo). */
export async function hablar(texto: string): Promise<void> {
  const t = texto.trim();
  if (!t || sinIA) return;
  callar();
  const yo = ++actual;
  try {
    const r = await fetch("/api/voz/hablar", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ texto: t }) });
    if (r.status === 501) { sinIA = true; return; }
    if (!r.ok || yo !== actual) return;
    const blob = await r.blob();
    if (yo !== actual) return;
    const a = el();
    if (!a) return;
    const url = URL.createObjectURL(blob);
    await new Promise<void>((listo) => {
      const fin = () => { a.onended = a.onerror = a.onpause = null; URL.revokeObjectURL(url); listo(); };
      a.onended = fin; a.onerror = fin; a.onpause = () => { if (a.currentTime > 0 && !a.ended) fin(); };
      a.src = url; a.volume = 1;
      a.play().catch(fin);
    });
  } catch {}
}

export const hablando = () => !!audio && !audio.paused && !audio.ended;
